            a: '13 лет (принимается «почти 14»)',
            c: 'Кормилица уточняет: до четырнадцати ей осталось две недели с небольшим. А Ромео за пару часов до знакомства с ней страдал по другой девушке — Розалине. Вся история от встречи до трагедии уложилась примерно в пять дней.',
